window.fpMissionsForVenue = (venue) => {
  if (venue && venue.packTemplate === "exhibits") return window.FIELD_PACK_MISSIONS_EXHIBITS;
  if (venue && (venue.packTemplate === "park_features" || venue.type === "national_park")) {
    return window.FIELD_PACK_MISSIONS_PARK;
  }
  return window.FIELD_PACK_MISSIONS_ANIMALS;
};
